## 5️⃣ TL;DR – copy-paste ready snippet

```kotlin
// In your Application class (or before the first MapView)
class MyApp : Application() {
    override fun onCreate() {
        super.onCreate()
        installVaultModuleProvider()
    }

    private fun installVaultModuleProvider() {
        val stock = MapLibre.getModuleProvider()
        MapLibre.setModuleProvider(object : ModuleProvider by stock {
            override fun createHttpRequest(): HttpRequest =
                VaultHttpRequest(stock.createHttpRequest())
        })
    }
}

// The request wrapper
class VaultHttpRequest(private val stock: HttpRequest) : HttpRequest {
    override fun executeRequest(
        responder: HttpResponder,
        nativePtr: Long,
        resourceUrl: String,
        dataRange: String?,
        etag: String?,
        modified: String?,
        offlineUsage: Boolean
    ) {
        if (!resourceUrl.startsWith("vault://")) {
            stock.executeRequest(
                responder, nativePtr, resourceUrl,
                dataRange, etag, modified, offlineUsage
            )
            return
        }

        try {
            val bytes = Vault.decryptTile(resourceUrl)   // <-- your decryption
            responder.onResponse(200, null, null, null, null, null, null, bytes)
        } catch (e: Exception) {
            responder.handleFailure(HttpRequest.ResponseType.PERMANENT_ERROR,
                e.message ?: "Vault error")
        }
    }

    override fun cancelRequest() = stock.cancelRequest()
}
```

